package com.pranit.productsupport.core.service;
import com.pranit.productsupport.contracts.*; import com.pranit.productsupport.core.domain.*; import com.pranit.productsupport.core.repository.*; import java.util.List; import java.util.Locale; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CatalogOrderService {
 private final ProductRepository products;private final AppUserRepository users;private final OrderRepository orders;
 public CatalogOrderService(ProductRepository p,AppUserRepository u,OrderRepository o){products=p;users=u;orders=o;}
 @Transactional(readOnly=true) public List<ProductResponse> listProducts(){return products.findByActiveTrueOrderByNameAsc().stream().map(this::productDto).toList();}
 @Transactional public ProductResponse createProduct(CreateProductRequest r){if(products.existsBySkuIgnoreCase(r.sku().trim()))throw ApiException.conflict("SKU already exists");return productDto(products.save(new Product(r.sku().trim(),r.name().trim(),r.description())));}
 @Transactional public OrderResponse createOrder(CreateOrderRequest r){AppUser customer=users.findByEmail(r.customerEmail().trim().toLowerCase(Locale.ROOT)).orElseThrow(()->ApiException.notFound("Customer not found"));OrderStatus status;try{status=r.status()==null?OrderStatus.DELIVERED:OrderStatus.valueOf(r.status().toUpperCase(Locale.ROOT));}catch(IllegalArgumentException e){throw new ApiException(HttpStatus.BAD_REQUEST,"Unsupported order status");}PurchaseOrder order=new PurchaseOrder(customer,status);for(OrderLineRequest line:r.items()){Product p=products.findById(line.productId()).orElseThrow(()->ApiException.notFound("Product not found: "+line.productId()));if(!p.isActive())throw new ApiException(HttpStatus.CONFLICT,"Inactive product cannot be ordered");if(line.quantity()<1||line.quantity()>1000)throw new ApiException(HttpStatus.BAD_REQUEST,"Quantity must be between 1 and 1000");order.addItem(new OrderItem(order,p,line.quantity()));}return orderDto(orders.save(order));}
 @Transactional(readOnly=true) public List<OrderResponse> myOrders(Long userId){return orders.findByCustomer_IdOrderByCreatedAtDesc(userId).stream().map(this::orderDto).toList();}
 private ProductResponse productDto(Product p){return new ProductResponse(p.getId(),p.getSku(),p.getName(),p.getDescription(),p.isActive());}
 private OrderResponse orderDto(PurchaseOrder o){return new OrderResponse(o.getId(),o.getCustomer().getEmail(),o.getStatus().name(),o.getCreatedAt(),o.getItems().stream().map(i->new OrderLineResponse(i.getId(),i.getProduct().getId(),i.getProduct().getSku(),i.getProduct().getName(),i.getQuantity())).toList());}
}
